import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice: happy path with single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(result, {
    ok: true,
    value: {
      customerId: 'C-001',
      issueDate: '2024-10-15',
      status: 'draft',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
        },
      ],
    },
  });
});

test('createInvoice: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-01-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-003');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 3);
  assert.deepEqual(result.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
  });
  assert.deepEqual(result.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  });
});

