test('issueInvoice: does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const original = JSON.parse(JSON.stringify(invoiceResult.value));

  issueInvoice(invoiceResult.value, []);

  assert.deepEqual(invoiceResult.value, original);
  assert.equal(invoiceResult.value.status, 'draft');
  assert.equal(invoiceResult.value.number, undefined);
});

test('issueInvoice: multiple invoices get unique numbers', () => {
  const invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const issued1 = issueInvoice(invoice1Result.value, []);
  const issued2 = issueInvoice(invoice2Result.value, [issued1.value.number]);

  assert.equal(issued1.value.number, 'INV-2024-0001');
  assert.equal(issued2.value.number, 'INV-2024-0002');
});

test('issueInvoice: different years get separate counters', () => {
  const invoice2023Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-12-31',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice2024Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });

  const issued2023 = issueInvoice(invoice2023Result.value, ['INV-2023-0050']);
  const issued2024 = issueInvoice(
    invoice2024Result.value,
    ['INV-2023-0050', issued2023.value.number]
  );

  assert.equal(issued2023.value.number, 'INV-2023-0051');
  assert.equal(issued2024.value.number, 'INV-2024-0001');
});

test('issueInvoice: after edit with addLine', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const afterAdd = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  const result = issueInvoice(afterAdd.value, []);

  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2024-0001');
  assert.equal(result.value.lines.length, 2);
});
